sys_script.script:
(function executeRule(current, previous /*null when async*/) {

      var plainPassword = generatePassword();
      current.password = plainPassword;
  function generatePassword() {
    var chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789@#';
    var pass = '';
    for (var i = 0; i < 10; i++) {
      pass += chars.charAt(Math.floor(Math.random() * chars.length));
    }
    return pass;
  }

  var mail = new GlideEmailOutbound();
  mail.setSubject("Your account has been created");
  mail.setFrom("noreply@example.com");
  mail.setTo(current.email); 
  mail.setBody(
    "Hello " + current.name + ",\n\n" +
    "Your account has been created.\n\n" +
    "Username: " + current.email + "\n" +
    "Temporary Password: " + plainPassword + "\n\n" +
    "Please log in and change your password immediately.\n\n" +
    "Regards,\nSupport Team"
  );
  mail.send();



})(current, previous);
